import assert from 'node:assert/strict';import {createHash} from 'node:crypto';import {readFileSync} from 'node:fs';import {execFileSync} from 'node:child_process';import {withoutAuftrag18} from './auftrag18.mjs';
const c=JSON.parse(readFileSync(new URL('./rent-guide-authorized-change.json',import.meta.url),'utf8'));const hash=b=>createHash('sha256').update(b).digest('hex');
export function withoutRentGuide(path,bytes){const key=path.startsWith('frontend/')?path:'frontend/'+path;const preserved=withoutAuftrag18(key,bytes);if(key!==c.path)return preserved;let normalized=preserved.toString();const a18="sections.filter(s=>s.id!=='ueber').map(s=>";const occurrences=normalized.split(a18).length-1;if(occurrences===1)normalized=normalized.replace(a18,'sections.map(s=>');else assert.equal(occurrences,0,'Die A18-Navigationsänderung muss einmalig und gezielt sein');assert.equal(hash(normalized),c.after,'Exakt geprüfte Menü-/Routingergänzung für Auftrag 17 plus A18');const old=execFileSync('git',['show',c.base+':'+key],{maxBuffer:16e6});assert.equal(hash(old),c.before);return old}
